package com.xmission.trevin.android.tangram.ui;

import android.app.Activity;
import android.graphics.Bitmap;
import android.graphics.Canvas;
import android.graphics.Shader;
import android.graphics.drawable.BitmapDrawable;
import android.graphics.drawable.Drawable;
import android.view.View;

import androidx.annotation.DrawableRes;
import androidx.annotation.NonNull;
import androidx.appcompat.content.res.AppCompatResources;

/**
 * Helper for tiling a drawable across an activity&rsquo;s background.
 *
 * @author Claude Opus 4.8
 */
public final class BackgroundTiler {

    private BackgroundTiler() {
    }

    /**
     * Tile the given drawable across the activity&rsquo;s content area at a
     * fixed pixel size instead of stretching it.  The drawable is rasterized
     * once at its intrinsic size (so a vector authored in dp becomes a bitmap
     * of that many display pixels) and repeated with {@link Shader.TileMode#REPEAT}.
     *
     * <p>This is the reliable way to tile a {@code VectorDrawable}: the
     * {@code <bitmap android:tileMode="repeat">} resource element requires a
     * raster source and does not tile a vector on API&nbsp;23.</p>
     *
     * @param activity the activity whose content background to set
     * @param tileRes the drawable to tile
     */
    public static void applyTiledBackground(@NonNull Activity activity,
                                            @DrawableRes int tileRes) {
        View content = activity.findViewById(android.R.id.content);
        Drawable tile = AppCompatResources.getDrawable(activity, tileRes);
        if (content == null || tile == null)
            return;
        int width = Math.max(1, tile.getIntrinsicWidth());
        int height = Math.max(1, tile.getIntrinsicHeight());
        Bitmap bitmap = Bitmap.createBitmap(2*width, 2*height,
                Bitmap.Config.ARGB_8888);
        Canvas canvas = new Canvas(bitmap);
        tile.setBounds(0, 0, width, height);
        for (int i = 0; i < 4; i++) {
            canvas.save();
            canvas.translate((i & 2) == 0 ? 0 : width,
                    (i & 1) == 0 ? 0 : height);
            canvas.rotate(90 * i, width / 2, height / 2);
            tile.draw(canvas);
            canvas.restore();
        }
        BitmapDrawable tiled = new BitmapDrawable(activity.getResources(), bitmap);
        tiled.setTileModeXY(Shader.TileMode.REPEAT, Shader.TileMode.REPEAT);
        content.setBackground(tiled);
    }
}